def solve(g):
    H=len(g); W=len(g[0])
    srows=[r for r in range(H) if all(x==8 for x in g[r])]
    scols=[c for c in range(W) if all(g[r][c]==8 for r in range(H))]
    rb=bands(srows,H); cb=bands(scols,W)
    pos=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if g[r][c] in (2,3): pos[g[r][c]].append((r,c))
    o=[[x for x in row] for row in g]
    def colband(c): return next(i for i,(a,b) in enumerate(cb) if a<=c<=b)
    def rowband(r): return next(i for i,(a,b) in enumerate(rb) if a<=r<=b)
    # classify each color: vertical if markers span >=2 rowbands else horizontal
    paints={}  # color -> list of (cell type)
    for col,cells in pos.items():
        rbs_=sorted(set(rowband(r) for r,_ in cells))
        cbs_=sorted(set(colband(c) for _,c in cells))
        if len(rbs_)>1:
            # vertical: fill each marker's column band entirely (all rows)
            for cc in cbs_:
                for c in range(cb[cc][0],cb[cc][1]+1):
                    paints.setdefault(col,[]).append(('v',c))
        else:
            for rr in rbs_:
                for r in range(rb[rr][0],rb[rr][1]+1):
                    paints.setdefault(col,[]).append(('h',r))
    res=[[g[i][j] for j in range(W)] for i in range(H)]
    # draw all paints; count layers
    L=[]
    for col,Lst in paints.items():
        for typ,val in Lst:
            if typ=='v': L.append((col,[r for r in range(H)],val))
            else: L.append((col,[c for c in range(W)],val))
    # resolve: intersecting regions -> 6
    segs=[]
    for col,rows,val in L:
        segs.append((col,set(rows),val))
    six=set()
    for a in segs:
        for b in segs:
            if a is not b and a[2]==b[2]: continue
            inter=sorted(set(a[1]&b[1]))
            if inter:
                for r in inter:
                    for c in (a[3],) if False else []: pass
    # simpler: paint once, then second pass overwrite, third pass =6
    cur=[[0]*W for _ in range(H)]
    cnt=[[0]*W for _ in range(H)]
    for col,rows,val in L:
        for r in rows:
            for c in (val,) if False else []: pass
    # vertical: val = column index
    for col,rows,val in L:
        for r in rows: cur[r][val]=col; cnt[r][val]+=1
    for col,rows,val in L:
        for c in rows: cur[val][c]=col; cnt[val][c]+=1
    for i in range(H):
        for j in range(W):
            if cnt[i][j]>1: res[i][j]=6
            else: res[i][j]=cur[i][j] if cur[i][j]!=0 else g[i][j]
    return res
