    # compute spans per color as rectangles: rowband-span x colband-span covering all cells of that color
    for col in (2,3):
        rs=sorted(set(rb[r] for r,_ in pos[col])); cs_=sorted(set(cb[c] for _,c in pos[col]))
        rects[col]=(min(rs),max(rs),min(cs_),max(cs_))
